/**
 * Reconstruction sampling harness (Fix Round 5, 3.5; ADR-072).
 *
 * For each model configuration: run the training to completion; sample N positions with a seeded generator; at each
 * position, reconstruct the execution state three ways and compare them value by value, bit for bit:
 *  1. **from the trace alone:** the complete trace serialised to its JSON file format, parsed back, and read with no
 *     engine (memorySource);
 *  2. **from checkpoints:** the TraceStore with a cache budget of one byte, so every segment read is regenerated by
 *     re-running one batch from its checkpoint (the deployed design, at its most demanding);
 *  3. **the reference:** a fresh engine run from the seed, halted at that position: its instructions up to the
 *     position are kept in memory and nothing after it is ever computed.
 * A position matches when 1 and 2 are both bit-identical to 3 in every value of the state: every parameter version,
 * every value of the current example's forward and backward pass, the current instruction's results, the batch
 * gradients, the losses and the latest evaluation.
 *
 * Also measured: the time to reconstruct from checkpoints against the distance from the position to the segment's
 * checkpoint, and memory as a reduction factor against retaining every value.
 *
 * Output: reports/reconstruction.json. Usage:
 *   NODE_OPTIONS=--max-old-space-size=8000 npx tsx --tsconfig tsconfig.tsx.json scripts/measure-reconstruction.ts
 * (RECON_N sets samples per configuration; default 834, so 12 configurations give 10,008.)
 */
import { createHash } from 'node:crypto';
import { mkdirSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { registerAsset, resolveDataset } from '../src/core/engine/host';
import { TrainingSession, type TrainConfig } from '../src/core/engine/session';
import type { Dataset } from '../src/core/engine/datasets';
import {
  NpmEmitter,
  TraceStore,
  deserializeTrace,
  memorySource,
  reconstructState,
  serializeTrace,
  storeSource,
  type Instruction,
  type TraceSource,
} from '../src/core/npm';
import type { ExecState } from '../src/core/npm/state';
import type { Tensor } from '../src/core/tensor/tensor';
import { Rng } from '../src/core/rng/rng';
import { loadMnist } from '../src/experiments/data/mnist';
import { EXPERIMENTS } from '../src/experiments/registry';

registerAsset('mnist-012', loadMnist);

const ROOT = resolve(import.meta.dirname, '..');
const N = Number(process.env.RECON_N ?? 834);
const SEED = 20261104;

interface Configuration {
  id: string;
  config: TrainConfig;
  data: Dataset;
}

/** Every available curriculum experiment, plus two variants that exercise other code paths. */
function configurations(): Configuration[] {
  const out: Configuration[] = EXPERIMENTS.filter((e) => e.status === 'available').map((e) => ({
    id: e.id,
    config: e.config,
    data: resolveDataset(e.dataset),
  }));
  const xor = EXPERIMENTS.find((e) => e.id === 'xor-mlp')!;
  out.push({
    id: 'xor-mlp, momentum and ReLU (variant)',
    config: {
      ...xor.config,
      optimizer: { type: 'momentum', lr: 0.1, momentum: 0.9 },
      model: {
        ...xor.config.model,
        layers: xor.config.model.layers.map((l, k, a) =>
          k < a.length - 1 && l.type === 'dense' ? { ...l, activation: 'relu' as const } : l,
        ),
      },
    },
    data: resolveDataset(xor.dataset),
  });
  const gd = EXPERIMENTS.find((e) => e.id === 'gradient-descent')!;
  out.push({
    id: 'gradient-descent, diverging learning rate (variant)',
    config: { ...gd.config, optimizer: { ...gd.config.optimizer, lr: 5 } as TrainConfig['optimizer'] },
    data: resolveDataset(gd.dataset),
  });
  return out;
}

/**
 * The reference: one fresh execution from the seed. When it emits a sampled position, the state there is read from
 * the instructions emitted so far, before the engine computes anything after it: the run "halted at that position".
 * (One run serves every sampled position of the configuration; each read sees only the prefix.)
 */
function references(
  c: Configuration,
  header: TraceSource['header'],
  at: Set<number>,
): Map<number, [string, number][]> {
  const session = new TrainingSession(c.config, c.data);
  const got: Instruction[] = [];
  const out = new Map<number, Packed>();
  // The prefix as a source: the segment index is grown as instructions arrive (memorySource's own rule).
  const starts: number[] = [0];
  const prefix: TraceSource = {
    header,
    get length() {
      return got.length;
    },
    get: (id) => {
      if (id >= got.length) throw new Error(`reference read ${id} beyond the halt at ${got.length - 1}`);
      return got[id];
    },
    range: (a, b) => {
      if (b > got.length) throw new Error(`reference read up to ${b} beyond the halt at ${got.length - 1}`);
      return got.slice(a, b);
    },
    segmentBounds: (id) => {
      let lo = 0;
      let hi = starts.length - 1;
      while (lo < hi) {
        const mid = (lo + hi + 1) >> 1;
        if (starts[mid] <= id) lo = mid;
        else hi = mid - 1;
      }
      // The current segment ends where the next one starts, or (still open) at the halt.
      return [starts[lo], starts[lo + 1] ?? got.length];
    },
  };
  const emitter = new NpmEmitter(session, (i) => {
    const k = i.kind;
    if (
      got.length > 0 &&
      (k === 'EPOCH_BEGIN' || (k === 'BATCH_BEGIN' && got[got.length - 1].kind !== 'EPOCH_BEGIN'))
    )
      starts.push(got.length);
    got.push(i);
    if (at.has(i.id)) out.set(i.id, pack(values(reconstructState(prefix, i.id))));
  });
  emitter.emitPrologue();
  while (!session.done)
    for (let b = 0; b < session.batchesPerEpoch; b++) {
      if (b === 0) session.beginEpoch(emitter);
      session.runBatch(emitter);
      if (b === session.batchesPerEpoch - 1) session.endEpoch(emitter);
    }
  return out;
}

/** Every number of a state, in a fixed order, with its name: what "the state" means for the comparison. */
function values(s: ExecState): [string, number][] {
  const out: [string, number][] = [];
  const t = (name: string, x: Tensor | null | undefined): void => {
    if (!x) return;
    for (let k = 0; k < x.data.length; k++) out.push([`${name}[${k}]`, x.data[k]]);
  };
  out.push(['cursor', s.cursor], ['completedEpochs', s.completedEpochs]);
  for (const [n, p] of Object.entries(s.params).sort()) {
    out.push([`${n}.producedBy`, p.producedBy]);
    t(n, p.value);
  }
  for (const [n, g] of Object.entries(s.lastGrads).sort()) t(`grad ${n}`, g);
  if (s.current) for (const [n, r] of Object.entries(s.current.results).sort()) t(`current.${n}`, r);
  if (s.sample) {
    out.push(['sample.datasetIndex', s.sample.datasetIndex]);
    t('sample.x', s.sample.x);
    t('sample.y', s.sample.y);
    if (s.sample.loss !== undefined) out.push(['sample.loss', s.sample.loss]);
    for (const [l, ls] of Object.entries(s.sample.layers).sort())
      for (const [f, v] of Object.entries(ls).sort()) t(`${l}.${f}`, v as Tensor);
  }
  if (s.batchLoss !== undefined) out.push(['batchLoss', s.batchLoss]);
  if (s.lastEval) out.push(['eval.loss', s.lastEval.loss], ['eval.accuracy', s.lastEval.accuracy ?? NaN]);
  return out;
}

/** A state held compactly: a hash of its value names, in order, and the values (the bits are compared). */
interface Packed {
  names: string;
  data: Float64Array;
}
function pack(v: [string, number][]): Packed {
  return {
    names: createHash('sha256')
      .update(v.map((x) => x[0]).join('\n'))
      .digest('hex'),
    data: Float64Array.from(v, (x) => x[1]),
  };
}

const bits = (v: number): string => {
  const b = new DataView(new ArrayBuffer(8));
  b.setFloat64(0, v);
  return b.getBigUint64(0).toString(16);
};

/** First difference between two states, or null if every value is bit-identical. */
function differ(a: [string, number][], ref: Packed): string | null {
  if (a.length !== ref.data.length) return `different number of values (${a.length} vs ${ref.data.length})`;
  if (pack(a).names !== ref.names) return 'the values are named differently';
  for (let k = 0; k < a.length; k++)
    if (bits(a[k][1]) !== bits(ref.data[k])) return `${a[k][0]}: ${a[k][1]} vs ${ref.data[k]}`;
  return null;
}

const quantile = (xs: number[], q: number): number => {
  const s = [...xs].sort((x, y) => x - y);
  return s[Math.min(s.length - 1, Math.floor(q * s.length))];
};

const results: unknown[] = [];
const rng = new Rng(SEED);
let totalPositions = 0;
let totalValues = 0;
let totalMatches = 0;
for (const c of configurations()) {
  const t0 = performance.now();
  const full = TraceStore.generate(c.config, c.data, { budgetBytes: Infinity }).store;
  // The file format, in chunks of instructions: a CNN trace is longer than the longest string a JS engine allows,
  // so each chunk is written and parsed as a complete trace file and the instructions are concatenated.
  const parsed: Instruction[] = [];
  let fileHeader = full.header;
  for (let a = 0; a < full.length; a += 5000) {
    const t = deserializeTrace(
      serializeTrace({ header: full.header, instructions: full.range(a, Math.min(full.length, a + 5000)) }),
    );
    fileHeader = t.header;
    parsed.push(...t.instructions);
  }
  const fileTrace = { header: fileHeader, instructions: parsed };
  const fromFile = memorySource(fileTrace);
  const { store } = TraceStore.generate(c.config, c.data, { budgetBytes: 1 });
  const fromCheckpoints = storeSource(store);
  const stats = full.stats();
  const lowStats = store.stats();

  const cursors = Array.from({ length: N }, () => rng.int(full.length));
  const refs = references(c, full.header, new Set(cursors));
  const samples: { cursor: number; distance: number; ms: number; values: number; mismatch: string | null }[] =
    [];
  for (const cursor of cursors) {
    const reference = refs.get(cursor)!;
    const a = values(reconstructState(fromFile, cursor));
    const t1 = performance.now();
    const b = values(reconstructState(fromCheckpoints, cursor));
    const ms = performance.now() - t1;
    const mismatch = differ(a, reference) ?? differ(b, reference);
    samples.push({
      cursor,
      distance: cursor - store.segmentOf(cursor).start,
      ms,
      values: reference.data.length,
      mismatch: mismatch && `${mismatch}`,
    });
  }
  const matched = samples.filter((s) => !s.mismatch).length;
  const nValues = samples.reduce((a, s) => a + s.values, 0);
  totalPositions += samples.length;
  totalValues += nValues;
  totalMatches += matched;
  // Cost against distance from the checkpoint, in quartiles of distance.
  const byDistance = [...samples].sort((x, y) => x.distance - y.distance);
  const curve = [0, 1, 2, 3].map((q) => {
    const part = byDistance.slice(
      Math.floor((q * byDistance.length) / 4),
      Math.floor(((q + 1) * byDistance.length) / 4),
    );
    return {
      distanceFrom: part[0]?.distance ?? 0,
      distanceTo: part.at(-1)?.distance ?? 0,
      medianMs: quantile(
        part.map((s) => s.ms),
        0.5,
      ),
      p95Ms: quantile(
        part.map((s) => s.ms),
        0.95,
      ),
    };
  });
  const retainedBytes = lowStats.checkpointBytes + lowStats.cachedBytes;
  const r = {
    id: c.id,
    instructions: full.length,
    segments: stats.segments,
    positions: samples.length,
    valuesCompared: nValues,
    matched,
    mismatches: samples.filter((s) => s.mismatch).slice(0, 5),
    reconstructionMs: {
      median: quantile(
        samples.map((s) => s.ms),
        0.5,
      ),
      p95: quantile(
        samples.map((s) => s.ms),
        0.95,
      ),
      max: Math.max(...samples.map((s) => s.ms)),
    },
    costByCheckpointDistance: curve,
    memory: {
      fullBytes: stats.fullBytes,
      retainedBytes,
      reductionFactor: stats.fullBytes / Math.max(1, retainedBytes),
    },
    seconds: (performance.now() - t0) / 1000,
  };
  results.push(r);
  console.log(
    `${c.id}: ${matched}/${samples.length} positions bit-identical, ${nValues.toLocaleString('en')} values, ` +
      `median ${r.reconstructionMs.median.toFixed(2)} ms, memory ÷${r.memory.reductionFactor.toFixed(1)}, ${r.seconds.toFixed(0)} s`,
  );
}

const report = {
  generatedBy: 'scripts/measure-reconstruction.ts',
  seed: SEED,
  samplesPerConfiguration: N,
  node: process.version,
  platform: `${process.platform}-${process.arch}`,
  configurations: results.length,
  positions: totalPositions,
  valuesCompared: totalValues,
  matchedPositions: totalMatches,
  matchRate: totalMatches / Math.max(1, totalPositions),
  results,
};
mkdirSync(resolve(ROOT, 'reports'), { recursive: true });
writeFileSync(resolve(ROOT, 'reports/reconstruction.json'), JSON.stringify(report, null, 2) + '\n');
console.log(
  `\n${report.configurations} configurations, ${totalPositions} positions, ${totalValues.toLocaleString('en')} values: ${totalMatches} positions bit-identical (${(report.matchRate * 100).toFixed(2)} %).`,
);
